function b64urlToBytes(s) {
  s = s.replace(/-/g, "+").replace(/_/g, "/");
  while (s.length % 4) s += "=";
  const bin = atob(s), out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}
const b64urlJSON = (s) => JSON.parse(new TextDecoder().decode(b64urlToBytes(s)));
async function accessKeys(team, fetchImpl) {
  const now = Date.now();
  if (certCache.team === team && now - certCache.at < CERT_TTL_MS && certCache.keys.length) return certCache.keys;
  const res = await fetchImpl(`https://${team}/cdn-cgi/access/certs`);
  if (!res.ok) throw new Error("certs " + res.status);
  const j = await res.json();
  certCache = { at: now, team, keys: Array.isArray(j.keys) ? j.keys : [] };
  return certCache.keys;
}
/** True only for a token Cloudflare Access issued for THIS application, unexpired. */
async function verifyAccessJwt(token, env, fetchImpl = fetch, nowSec = Math.floor(Date.now() / 1000)) {
  const team = env.ACCESS_TEAM_DOMAIN, aud = env.ACCESS_AUD;
  if (!token || !team || !aud) return false;
  const parts = token.split(".");
  if (parts.length !== 3) return false;
  let header, payload;
  try { header = b64urlJSON(parts[0]); payload = b64urlJSON(parts[1]); } catch (_) { return false; }
  if (header.alg !== "RS256" || !header.kid) return false;
  let keys;
  try { keys = await accessKeys(team, fetchImpl); } catch (_) { return false; }
  const jwk = keys.find((k) => k.kid === header.kid);
  if (!jwk) return false;
  let ok = false;
  try {
    const key = await crypto.subtle.importKey("jwk", { kty: jwk.kty, n: jwk.n, e: jwk.e, alg: "RS256", ext: true },
      { name: "RSASSA-PKCS1-v1_5", hash: "SHA-256" }, false, ["verify"]);
    ok = await crypto.subtle.verify("RSASSA-PKCS1-v1_5", key, b64urlToBytes(parts[2]), new TextEncoder().encode(parts[0] + "." + parts[1]));
  } catch (_) { return false; }
  if (!ok) return false;
  const auds = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
  if (!auds.includes(aud)) return false;
  if (payload.iss !== `https://${team}`) return false;
  if (typeof payload.exp !== "number" || payload.exp <= nowSec) return false;
  if (typeof payload.nbf === "number" && payload.nbf > nowSec + 60) return false;
  return true;
}

/* ---------- password mode ---------- */
async function sameSecret(a, b) {
  const enc = new TextEncoder();
  const [x, y] = await Promise.all([crypto.subtle.digest("SHA-256", enc.encode(a)), crypto.subtle.digest("SHA-256", enc.encode(b))]);
  const u = new Uint8Array(x), v = new Uint8Array(y);
  let diff = 0;
  for (let i = 0; i < u.length; i++) diff |= u[i] ^ v[i];
  return diff === 0;
}
async function passwordOk(req, env) {
  if (!env.SITE_PASSWORD) return false;
  const h = req.headers.get("authorization") || "";
  if (!h.startsWith("Basic ")) return false;
  let d = "";
  try { d = atob(h.slice(6)); } catch (_) { return false; }
  return sameSecret(d.slice(d.indexOf(":") + 1), env.SITE_PASSWORD);
}
/** null when the request may proceed; otherwise the refusal to send. */
async function gate(req, env, fetchImpl = fetch) {
  if (env.GATE_MODE === "access") return (await verifyAccessJwt(req.headers.get("cf-access-jwt-assertion"), env, fetchImpl)) ? null : deny(403, "Forbidden");
  if (env.GATE_MODE === "password") return (await passwordOk(req, env)) ? null : deny(401, "Login required", { "www-authenticate": 'Basic realm="ETHKROS", charset="UTF-8"' });
  return deny(503, "Site gate not configured");
}

/* ---------- data ---------- */
function csvToBars(text) {
  const lines = text.trim().split(/\r?\n/);
  const head = lines.shift().split(",");
  const col = (k) => head.indexOf(k);
  const [it, io, ih, il, ic] = ["time", "open", "high", "low", "close"].map(col);
  if ([it, io, ih, il, ic].some((i) => i < 0)) throw new Error("bad candle header");
  return lines.map((l) => { const c = l.split(","); return { t: +c[it], o: +c[io], h: +c[ih], l: +c[il], c: +c[ic] }; })
    .filter((b) => [b.t, b.o, b.h, b.l, b.c].every(Number.isFinite));
}
async function upstream(env, from, path) {
  const svc = env[from];
  if (!svc || typeof svc.fetch !== "function") return null;
  try { return await svc.fetch(new Request("https://" + from.toLowerCase() + path, { method: "GET" })); } catch (_) { return null; }
}
const dataHeaders = (type) => ({ "content-type": type, "cache-control": "no-store", ...SEC_HEADERS });

async function handle(req, env, fetchImpl = fetch) {
  if (req.method !== "GET" && req.method !== "HEAD") return deny(405, "GET only");
  const refused = await gate(req, env, fetchImpl);
  if (refused) return refused;
  const p = new URL(req.url).pathname;
  if (p === "/" || p === "/index.html")
    return new Response(PAGE, { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "content-security-policy": PAGE_CSP, ...SEC_HEADERS } });
  if (p === "/data/example_ETH-2D-2024-09-22.json") return new Response(EXAMPLE, { headers: dataHeaders("application/json; charset=utf-8") });
  if (FIXED[p]) {
    const f = FIXED[p], r = await upstream(env, f.from, f.path);
    if (!r) return deny(502, "Data source unavailable");
    if (!r.ok) return deny(r.status === 404 ? 404 : 502, r.status === 404 ? "Not available" : "Data source unavailable");
    return new Response(r.body, { headers: dataHeaders(f.type) });
  }
  const m = p.match(CANDLES);
  if (m) {
    const r = await upstream(env, "MIRROR", `/datasets/candles_${m[1].toLowerCase()}_${m[2].toLowerCase()}.csv`);
    if (!r || !r.ok) return deny(r && r.status === 404 ? 404 : 502, "Candles unavailable");
    let bars;
    try { bars = csvToBars(await r.text()); } catch (_) { return deny(502, "Candles unreadable"); }
    return new Response(JSON.stringify({ chart: `${m[1]} ${m[2]}`, bars }), { headers: dataHeaders("application/json; charset=utf-8") });
  }
  return deny(404, "Not found");
}

export default {
  async fetch(req, env) { return handle(req, env); },
};
